with v(id,beschr,website,missie,plaats,bmin,bmax,btoel,bron) as (values
('f168f7b4-c451-456b-97d0-b32da3252265','Stichting Goede Doelen Nh1816 is het fonds van verzekeraar Nh1816 en steunt maatschappelijk relevante projecten van Nederlandse organisaties die weinig beroep kunnen doen op subsidies. Thema''s zijn veiligheid (hulp aan mensen in nood, veiligheidsbevordering), ziekte en handicap (participatie en kwaliteit van leven), educatie en talentontwikkeling (vooral jongeren tot en met 21 jaar) en cultuur (behoud van Nederlands cultureel en historisch erfgoed). Er zijn eenmalige giften voor kleinschalige projecten, meerjarige partnerprojecten en enkele substantiële sleutelprojecten. Aanvragers moeten een ANBI-status en KvK-inschrijving hebben; uitgesloten zijn religie, politiek, kunst, entertainment, medisch onderzoek en apparatuur, exploitatie- en personeelskosten en projecten buiten Nederland.',null,null,'Oudkarpsel',null,null,null,'https://www.NH1816.nl/Files/Files.new/SGD/SGDNh1816_Leidraad_v2024.pdf'),
('f17b35a4-2b15-426e-9231-f16cae163a84','Noaber Foundation is een Nederlandse familiestichting die zich ziet als ''pathfinder'' voor systeemverandering richting een gezonder en actiever leven. De stichting start en versnelt programma''s rond complexe gezondheidsvraagstukken en draagt die over aan grotere systeempartijen zodra ze zijn ingebed. Programma''s richten zich op sociale gezondheid, populatiegezondheid en leefstijl(geneeskunde), met als doel een langere gezonde levensduur. Daarnaast doet Noaber impactinvesteringen, vooral (pre-)seed, in ondernemingen op het gebied van gezondheidsactivatie, vroege screening en diagnostiek, slimme zorg voor chronische aandoeningen en zorgsystemen. Klassieke subsidieverstrekking wordt in de bron niet genoemd.',null,null,null,null,null,null,'https://impact-report2022.noaber.com/highlights-intro'),
('fea7cb39-f27a-411c-99e0-f92d2b44c553','Het Oranje Fonds bevordert betrokkenheid in de samenleving door sociale samenhang en sociale participatie te stimuleren, zodat mensen elkaar ontmoeten of een nieuwe plek in de maatschappij vinden. Het fonds steunt stichtingen en verenigingen; informele bewonersinitiatieven kunnen via een penvoerder aanvragen. Een voorbeeld is de regeling ''Reuring in de buurt'' voor nieuwe buurtactiviteiten door en voor bewoners, waarin minstens drie lokale organisaties samenwerken en ontmoetingen ontstaan tussen bewoners die elkaar normaal niet treffen (verschillend in leeftijd, migratieachtergrond, beperking of leefstijl). Het fonds draagt dan maximaal de helft van de kosten bij. Particulieren, bedrijven, fondsen en overheden kunnen niet aanvragen; reeds gemaakte kosten worden niet vergoed.',null,null,null,null,null,null,'https://www.oranjefonds.nl/sites/default/files/2022-07/Criteria%20Reuring%20in%20de%20Buurt.pdf'),
('355e335f-1dd6-47e5-89b9-25029e5e9252','De P.W. Janssen''s Friesche Stichting is een charitatief vermogensfonds dat ter nagedachtenis aan oprichter P.W. Janssen (1821-1903) maatschappelijke initiatieven ondersteunt in Amsterdam en Friesland. Volgens een Friese fondsenlijst draagt de stichting bij aan de bevordering van de volksontwikkeling in de provincie Friesland. Er is geen vast richtbedrag: de hoogte van de bijdrage hangt af van het project. Aanvragen worden schriftelijk ingediend. Specifieke doelgroepen of uitsluitingen worden in de geraadpleegde bron niet genoemd.',null,null,null,null,null,null,'https://www.noardeast-fryslan.nl/sites/default/files/2020-04/Fondsenlijst%20Partoer%202020_0.pdf'),
('7386df01-25f4-4c3e-9ae3-23ac449d8c14',null,null,null,'Laren',null,null,null,null),
('c143761f-4fda-4761-9998-8c805e447937','Het Cultuurfonds (sinds november 2023 zonder ''Prins Bernhard'' in de naam) steunt cultuur en natuur in Nederland en het Caribisch deel van het Koninkrijk en investeert jaarlijks ruim 35 miljoen euro in duizenden projecten. Gesteund worden onder meer podiumkunsten, muziek, beeldende kunst en tentoonstellingen, amateurkunst (fanfares, koren, toneelgroepen), cultuureducatie, natuurprojecten, wetenschap en geesteswetenschappen, en restauratie van bijzondere erfgoedobjecten en monumenten die toegankelijk zijn voor publiek. Via Cultuurfondsbeurzen gaan jaarlijks circa 150 pas afgestudeerden van kunstvakopleidingen, conservatoria en universiteiten verder studeren in het buitenland. Het fonds werkt met afdelingen in alle twaalf provincies, beheert fondsen op naam en ondersteunt amateurgroepen met crowdfunding.',null,null,'Amsterdam',null,null,null,'https://www.fondazionelangitalia.it/en/2018/01/29/prince-bernhard-cultuurfonds-serving-communities-since-1940/'),
('5d8d82c5-90ff-4dfa-a32d-07c0986c9cbb','De Rijksdienst voor het Cultureel Erfgoed (RCE) biedt met de Wind- en waterdichtregeling een subsidie voor noodmaatregelen aan monumentale gebouwen. De regeling is bedoeld om verder verval van erfgoed te voorkomen door een gebouw tijdelijk te beschermen tegen weersinvloeden, bijvoorbeeld door het dak, de gevels en openingen wind- en waterdicht te maken in afwachting van restauratie of herbestemming. De regeling richt zich op eigenaren van monumenten in slechte staat. Trefwoorden: monumentenzorg, noodmaatregelen, conservering, wind- en waterdicht maken, instandhouding gebouwd erfgoed, leegstaande monumenten, herbestemming. Werkgebied: heel Nederland.','https://www.cultureelerfgoed.nl/',null,'Amersfoort',null,null,null,'https://bbn.nl/wp-content/uploads/2021/04/Subsidies-Cultureel-Erfgoed_Whitepaper.pdf'),
('41f46b87-b9d6-45a7-a97b-cae69fd4a011','De Rotterdamse Stichting Blindenbelangen zet zich in voor het materiële, sociale en culturele welzijn van blinde en slechtziende mensen, met nadruk op inwoners van Rotterdam en omgeving. Het fonds steunt initiatieven en voorzieningen die de zelfredzaamheid, participatie en kwaliteit van leven van mensen met een visuele beperking vergroten, zoals sociale en culturele activiteiten en hulpmiddelen. Trefwoorden: blinden en slechtzienden, visuele beperking, welzijn, toegankelijkheid, sociale participatie, cultuurdeelname, Rotterdam.',null,null,'Rotterdam',null,null,null,null),
('2c7d177f-8f33-4e4b-a279-4fcae7427602','De Schumacher-Kramer Stichting (SK Foundation, SKF) is een betrokken financier die werkt aan betere gezondheid en meer welzijn voor de meest kwetsbare mensen. Het fonds ondersteunt organisaties en projecten die de gezondheid, het welzijn en de positie van mensen in een kwetsbare situatie verbeteren en stelt zich daarbij op als partner die meer biedt dan alleen geld. Trefwoorden: gezondheid, welzijn, kwetsbare groepen, betrokken filantropie, maatschappelijke impact.',null,null,null,null,null,null,null),
('db575275-554b-4397-8670-f2b260a33013','Sight and Life is een Zwitserse stichting die ondervoeding en tekorten aan micronutriënten bestrijdt in lage- en middeninkomenslanden. De organisatie richt zich in het bijzonder op vrouwen in de vruchtbare leeftijd en jonge kinderen. Zij ontwikkelt wetenschappelijk onderbouwde voedingsoplossingen om het voedingstekort te dichten en de cirkel van honger en armoede te doorbreken. Sight and Life voert sinds ongeveer 2019 ook zelf programma''s uit met lokale ondernemers en partners en schaalt bewezen aanpakken op via samenwerking met gevestigde organisaties. Het is eerder een uitvoerende organisatie en kennispartner dan een klassiek subsidieverstrekkend fonds. Trefwoorden: ondervoeding, micronutriënten, vitamine A, voedselzekerheid, moeder- en kindgezondheid, voedingsonderzoek, ontwikkelingslanden.',null,null,'Kaiseraugst (Zwitserland)',null,null,null,'https://sightandlife.org/our-story/'),
('8885fe47-206f-49b3-9680-94c78c5fd363','De Sint Bonifatius Stichting is een rooms-katholiek vermogensfonds dat gelieerd is aan de orde van de jezuïeten en van oudsher gevestigd is in het voormalige provincialaatsgebouw van de Nederlandse jezuïetenprovincie. Het fonds ondersteunt activiteiten en organisaties in de katholieke en jezuïtische traditie. Over de precieze bestedingscriteria, doelgroepen en het werkgebied is in de beschikbare gegevens geen nadere informatie gevonden. Trefwoorden: rooms-katholiek, jezuïeten, religie, kerkelijke initiatieven, levensbeschouwing.',null,null,null,null,null,null,null)
), u as (update public.funders f set
 algemene_beschrijving = coalesce(nullif(f.algemene_beschrijving,''), v.beschr),
 website = coalesce(nullif(f.website,''), v.website),
 missie = coalesce(nullif(f.missie,''), v.missie),
 plaats = coalesce(nullif(f.plaats,''), v.plaats),
 bijdrage_min = coalesce(f.bijdrage_min, v.bmin::numeric),
 bijdrage_max = coalesce(f.bijdrage_max, v.bmax::numeric),
 bijdrage_toelichting = coalesce(nullif(f.bijdrage_toelichting,''), v.btoel),
 bandbreedte_bijdrage_id = coalesce(f.bandbreedte_bijdrage_id, (select b.id from public.bandbreedtes_bijdrage b where coalesce(f.bijdrage_max, v.bmax::numeric) is not null and coalesce(f.bijdrage_max, v.bmax::numeric) > b.bedrag_min and (b.bedrag_max is null or coalesce(f.bijdrage_max, v.bmax::numeric) <= b.bedrag_max) order by b.volgorde limit 1)),
 research_source = coalesce(f.research_source,'') || case when f.research_source is null or f.research_source='' then '' else ' | ' end || 'Verrijking goedgekeurde fondsen ronde12, 17-10-2026 (Claude)',
 last_researched_at = now()
from v where f.id = v.id::uuid returning 1)
select count(*) bijgewerkt from u;